 * Reads all `.txt` files in `dir` and collects their non-empty, non-comment
 * lines as changeset IDs. Returns an empty Set if `dir` does not exist.
 */
export function readReleased (dir: string): Set<string> {
  const released = new Set<string>()
  if (!fs.existsSync(dir)) return released
  for (const entry of fs.readdirSync(dir)) {
    if (path.extname(entry) !== '.txt') continue
    collectIds(path.join(dir, entry), released)
  }
