 * Appends `ids` to the file for `branch` inside `dir`, deduplicating against
 * IDs already present in that file, then writes back the merged, sorted list
 * (one ID per line, trailing newline). No-op when `ids` is empty.
 */
export function appendReleased (dir: string, branch: string, ids: string[]): void {
  if (ids.length === 0) return
  fs.mkdirSync(dir, { recursive: true })
  const filePath = path.join(dir, branchToFilename(branch))
  const merged = new Set<string>()
  if (fs.existsSync(filePath)) {
    collectIds(filePath, merged)
  }
  for (const id of ids) {
    merged.add(id)
  }
  const sorted = Array.from(merged).sort()
  fs.writeFileSync(filePath, `${sorted.join('\n')}\n`)
