 * rename fails, all renames performed so far are rolled back and the original
 * error is re-thrown.
 */
export function hideReleased (dir: string, releasedIds: Set<string>): HiddenChangeset[] {
  const hidden: HiddenChangeset[] = []
  try {
    for (const entry of fs.readdirSync(dir)) {
      if (path.extname(entry) !== '.md') continue
      const id = entry.slice(0, -'.md'.length)
      if (!releasedIds.has(id)) continue
      const mdPath = path.join(dir, entry)
      const releasedPath = `${mdPath}.released`
      fs.renameSync(mdPath, releasedPath)
      hidden.push({ id, mdPath, releasedPath })
