/**
 * Renames each `.md.released` file referenced in `hidden` back to its original
 * `.md` filename.
 */
export function restoreHidden (hidden: HiddenChangeset[]): void {
  for (const changeset of hidden) {
    fs.renameSync(changeset.releasedPath, changeset.mdPath)
  }
}

/**
 * Permanently deletes each `.md.released` file referenced in `hidden`.
